import type { Lens, SimResult, Strategy } from './types';
import type { MonteCarloResult } from './montecarlo';
import type { ResolvedFact } from './reconcile';

/**
 * The advisor brief is a deterministic template over engine output. Every sentence
 * is traceable to a number in the ledger; nothing here is generated by a model.
 */

const usd = (x: number) => `${x < 0 ? '−' : ''}$${Math.abs(Math.round(x)).toLocaleString('en-US')}`;
const short = (x: number) => {
  const a = Math.abs(x);
  const s = a >= 1e6 ? `$${(a / 1e6).toFixed(2)}M` : `$${Math.round(a / 1e3)}k`;
  return x < 0 ? `−${s}` : s;
};
const pct = (x: number) => `${Math.round(x * 100)}%`;
export const STRATEGY_LABEL: Record<Strategy, string> = { hold: 'Hold', sell: 'Sell', exchange: '1031 Exchange' };
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

export interface BriefSection {
  heading: string;
  body: string;
}

export function advisorBrief(
  base: Record<Strategy, SimResult>,
  mc: MonteCarloResult | null,
  facts: ResolvedFact[],
  horizonYear: number,
  describe: (key: string) => string = (k) => k,
): BriefSection[] {
  const out: BriefSection[] = [];
  const sell = base.sell.transaction;
  const ex = base.exchange.transaction;

  if (mc) {
    const leader = (l: Lens) => (['hold', 'sell', 'exchange'] as Strategy[]).reduce((b, s) => (mc.winRate[l][s] > mc.winRate[l][b] ? s : b));
    const lq = leader('liquidation');
    const hr = leader('heirs');
    const p50 = (s: Strategy, l: Lens) => mc.bands[s][l].p50.at(-1)!;
    out.push({
      heading: 'The answer depends on how this ends',
      body:
        lq === hr
          ? `${STRATEGY_LABEL[lq]} finishes with the most wealth in ${pct(mc.winRate.liquidation[lq])} of ${mc.paths} simulated markets if everything is sold in ${horizonYear}, and in ${pct(mc.winRate.heirs[hr])} if it passes to heirs with a stepped-up basis.`
          : `If the client eventually cashes out (everything sold in ${horizonYear}, all tax paid), ${STRATEGY_LABEL[lq]} leads in ${pct(mc.winRate.liquidation[lq])} of ${mc.paths} simulated markets (median ${short(p50(lq, 'liquidation'))}). If the property passes to heirs, the §1014 step-up erases the deferred gain and ${STRATEGY_LABEL[hr]} leads in ${pct(mc.winRate.heirs[hr])} (median ${short(p50(hr, 'heirs'))}). The real question for the client is which of those endings is likely.`,
    });
  }

  if (sell) {
    const t = sell.taxImpact;
    out.push({
      heading: `Selling ${sell.propertyName} in ${MONTHS[sell.month - 1]} ${sell.year}`,
      body: `At ${usd(sell.price)}, the amount realized after ${usd(sell.sellingCosts)} of selling costs is ${usd(sell.amountRealized)}. Against an adjusted basis of ${usd(sell.adjustedBasis)} (${usd(sell.costBasis)} cost less ${usd(sell.depreciationTaken)} of depreciation), the gain is ${usd(sell.realizedGain)}. ${sell.unrecaptured1250 > 0 ? `${usd(sell.unrecaptured1250)} of that is depreciation coming back as unrecaptured §1250 gain, taxed at up to 25% (${usd(t.recapture1250)}); the remaining ${usd(sell.capitalGain)} is long-term gain (${usd(t.capitalGains)}). ` : ''}${sell.ordinaryLoss < 0 ? `It is a ${usd(-sell.ordinaryLoss)} §1231 loss, deductible against ordinary income. ` : ''}NIIT adds ${usd(t.niit)} and state tax ${usd(t.state)}.${sell.suspendedReleased > 0 ? ` The sale also frees ${usd(sell.suspendedReleased)} of suspended passive losses, worth ${usd(-t.ordinary)} against ordinary income.` : ''} Total tax: ${usd(t.total)}. Cash to the client after the ${usd(sell.loanPayoff)} payoff: ${usd(sell.netCash)}.`,
    });
  }

  if (ex) {
    out.push({
      heading: 'Exchanging instead',
      body: `Rolling ${usd(ex.amountRealized - ex.loanPayoff)} of equity into a ${usd(ex.replacementPrice!)} replacement (${usd(ex.replacementDebt!)} of new debt) ${ex.recognizedGain! > 0 ? `recognizes ${usd(ex.recognizedGain!)} of gain because debt relief of ${usd(ex.boot!)} counts as boot, and ` : ''}defers ${usd(ex.deferredGain!)} of gain. The deferral is not forgiveness: the replacement's basis is ${usd(ex.replacementBasis!)}, not its price, and ${usd(ex.depreciationTaken - (ex.unrecaptured1250 ?? 0))} of prior depreciation follows it, to be recaptured on any later taxable sale — unless the property is held until death. Depreciation continues on ${usd(ex.carryoverDepreciableBasis!)} of exchanged basis on the old schedule, plus ${usd(ex.excessDepreciableBasis!)} of new 27.5-year excess basis.${ex.suspendedCarried > 0 ? ` ${usd(ex.suspendedCarried)} of suspended losses stay suspended.` : ''}`,
    });
  }

  if (mc) {
    const lo = (s: Strategy) => mc.bands[s].liquidation.p10.at(-1)!;
    out.push({
      heading: 'What leverage costs in a bad market',
      body: `In the worst 10% of simulated markets, liquidation value in ${horizonYear} is ${short(lo('exchange'))} for the exchange, ${short(lo('hold'))} for holding, and ${short(lo('sell'))} for selling. The exchange adds real estate exposure and debt; this downside spread is what the client is being paid to accept.`,
    });
  }

  const chosen = facts.filter((f) => f.status === 'chosen');
  const owner = facts.filter((f) => f.source.kind === 'owner_asserted' || f.source.kind === 'estimate');
  if (chosen.length || owner.length)
    out.push({
      heading: 'What these numbers rest on',
      body: [
        ...chosen.map((f) => `${describe(f.key)} was resolved by the advisor to ${usd(f.value)} from "${f.source.document}" over ${f.alternatives.map((o) => `${usd(o.value)} ("${o.source.document}")`).join(', ')}.`),
        ...owner.filter((f) => f.status !== 'chosen').map((f) => `${describe(f.key)} relies on ${f.source.kind === 'estimate' ? 'an estimate' : "the owner's word"}: "${f.source.document}".`),
      ].join(' '),
    });
  return out;
}
